import csv
import collections
import statistics

rows = []
with open('/app/benchmark/data.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append(row)

# Filter out draws for win rate calculations
decisive = [r for r in rows if r['winner'] != 'draw']
print(f"Total decisive games (excl draws): {len(decisive)}")

white_wins = [r for r in decisive if r['winner'] == 'white']
black_wins = [r for r in decisive if r['winner'] == 'black']
print(f"White wins: {len(white_wins)}")
print(f"Black wins: {len(black_wins)}")
print(f"White win rate (decisive only): {len(white_wins)/len(decisive)*100:.2f}%")

# By victory status
print("\n=== WHITE WIN RATE BY VICTORY STATUS ===")
for status in ['mate', 'resign', 'outoftime']:
    status_white = [r for r in white_wins if r['victory_status'] == status]
    status_black = [r for r in black_wins if r['victory_status'] == status]
    total = len(status_white) + len(status_black)
    if total > 0:
        wr = len(status_white)/total*100
        print(f"  {status}: White {len(status_white)}/{total} = {wr:.2f}%")

# By rating bracket
print("\n=== WHITE WIN RATE BY RATING BRACKET ===")
def rating_bracket(r):
    r = int(r)
    if r < 1200: return '<1200'
    elif r < 1400: return '1200-1400'
    elif r < 1600: return '1400-1600'
    elif r < 1800: return '1600-1800'
    elif r < 2000: return '1800-2000'
    else: return '2000+'

bracket_counts = {b: {'white':0,'black':0} for b in ['<1200','1200-1400','1400-1600','1600-1800','1800-2000','2000+']}
for r in decisive:
    wb = rating_bracket(r['white_rating'])
    if r['winner'] == 'white':
        bracket_counts[wb]['white'] += 1
    else:
        bracket_counts[wb]['black'] += 1

for b in ['<1200','1200-1400','1400-1600','1600-1800','1800-2000','2000+']:
    w = bracket_counts[b]['white']
    bl = bracket_counts[b]['black']
    t = w + bl
    if t > 0:
        print(f"  {b}: White {w}/{t} = {w/t*100:.2f}%")

# By time control (grouped)
print("\n=== WHITE WIN RATE BY TIME CONTROL (GROUPED) ===")
def tc_group(tc):
    base = int(tc.split('+')[0])
    if base <= 5: return 'Bullet (<=5)'
    elif base <= 10: return 'Blitz (6-10)'
    elif base <= 25: return 'Rapid (11-25)'
    else: return 'Classical (26+)'

tc_counts = {}
for r in decisive:
    tg = tc_group(r['increment_code'])
    if tg not in tc_counts:
        tc_counts[tg] = {'white':0,'black':0}
    if r['winner'] == 'white':
        tc_counts[tg]['white'] += 1
    else:
        tc_counts[tg]['black'] += 1

for tg in ['Bullet (<=5)','Blitz (6-10)','Rapid (11-25)','Classical (26+)']:
    if tg in tc_counts:
        w = tc_counts[tg]['white']
        bl = tc_counts[tg]['black']
        t = w + bl
        if t > 0:
            print(f"  {tg}: White {w}/{t} = {w/t*100:.2f}%")

# By specific time controls (top 5)
print("\n=== WHITE WIN RATE BY TOP 5 TIME CONTROLS ===")
top_tc = ['10+0', '15+0', '15+15', '5+5', '5+8']
tc_counts_top = {}
for r in decisive:
    tc = r['increment_code']
    if tc in top_tc:
        if tc not in tc_counts_top:
            tc_counts_top[tc] = {'white':0,'black':0}
        if r['winner'] == 'white':
            tc_counts_top[tc]['white'] += 1
        else:
            tc_counts_top[tc]['black'] += 1

for tc in top_tc:
    if tc in tc_counts_top:
        w = tc_counts_top[tc]['white']
        bl = tc_counts_top[tc]['black']
        t = w + bl
        if t > 0:
            print(f"  {tc}: White {w}/{t} = {w/t*100:.2f}%")

